import { useState } from "react";

function ScoreForm({
	ranking,
	onRankingRender,
	onSetRanking,
	onUpdateRanking,
	team1,
	team2,
	onSelectTeam1,
	onSelectTeam2,
	team1Score,
	team2Score,
	onAddP1Score,
	onAddP2Score,
	onAddScore,
}) {
	// States
	const [point, setPoints] = useState(0);
	const [win, setWin] = useState(0);
	const [draw, setDraw] = useState(0);
	const [loss, setLoss] = useState(0);
	const [goalsFor, setGoalsFor] = useState(0);
	const [goalsAgainst, setGoalsAgainst] = useState(0);
	let goalsDifference = 0;
	// Handle submit form
	function handleSubmit(e) {
		e.preventDefault();

		// Build the new result, and add it into the scoreBoard state/table.
		const newResult = {
			id: Date.now(),
			homeTeam: team1,
			awayTeam: team2,
			result: team1Score + " : " + team2Score,
		};
		if (team1 && team2) {
			onAddScore(newResult);
		} else {
			alert("Select both teams, please.");
		}
		if (newResult) {
			if (team1Score > team2Score) {
				const team1NewStats = ranking.map((team) => {
					if (team.teamName === team1) {
						setPoints((point) => point + 3);
						setWin((win) => win + 1);
						setGoalsFor((goals) => goals + team1Score);
						setGoalsAgainst((goals) => goals + team2Score);
						goalsDifference = goalsFor - goalsAgainst;
					}
					return {
						...team,
						points: point,
						wins: win,
						draws: draw,
						losses: loss,
						goalsFor: goalsFor,
						goalsAgainst: goalsAgainst,
						goalDifference: goalsDifference,
					};
				});
				onSetRanking(team1NewStats);

				// const team1NewStats = {
				// 	points: point,
				// 	wins: win,
				// 	draws: draw,
				// 	losses: loss,
				// 	goalsFor: goalsFor,
				// 	goalsAgainst: goalsAgainst,
				// 	goalDifference: goalsDifference,
				// };
				//	onUpdateRanking(team1NewStats, team1);
				console.log(`points new state: ${point}`);
				console.log(`wins new state:${win}`);
				console.log(`GF: ${goalsFor}`);
				console.log(`GA: ${goalsAgainst}`);
				console.log(`Goals Diff: ${goalsDifference}`);
			} else if (team2Score > team1Score) {
				console.log("Player2 scored more goals!");
			} else {
				console.log("Tie! No winner today.");
			}
		} else {
			console.log("Nothing to update!");
		}
		// Re-render Ranking
		onRankingRender();
	}

	const playerObj = ranking.map((player) => player);
	const { teamName } = playerObj;

	return (
		<div className="scores">
			<form onSubmit={handleSubmit}>
				<span>
					<select
						defaultValue={"home"}
						value={teamName}
						onChange={(e) => onSelectTeam1(e.target.value)}
						required
					>
						<option value="home" disabled>
							Home Team
						</option>

						<option value={playerObj[0].teamName}>
							{playerObj[0].teamName}
						</option>
						<option value={playerObj[1].teamName}>
							{playerObj[1].teamName}
						</option>
						<option value={playerObj[2].teamName}>
							{playerObj[2].teamName}
						</option>
					</select>
					<input
						type="number"
						value={team1Score}
						onChange={(e) => onAddP1Score(Number(e.target.value))}
						required
					/>
				</span>
				:
				<span>
					<select
						defaultValue={"away"}
						value={teamName}
						onChange={(e) => onSelectTeam2(e.target.value)}
						required
					>
						<option value="away" disabled>
							Away Team
						</option>
						<option value={playerObj[0].teamName}>
							{playerObj[0].teamName}
						</option>
						<option value={playerObj[1].teamName}>
							{playerObj[1].teamName}
						</option>
						<option value={playerObj[2].teamName}>
							{playerObj[2].teamName}
						</option>
					</select>
					<input
						type="number"
						value={team2Score}
						onChange={(e) => onAddP2Score(Number(e.target.value))}
						required
					/>
				</span>
				<button>Add</button>
			</form>
		</div>
	);
}
export default ScoreForm;
